   126 static double __power_of(int x, int y)
   127 {
   128  int i;
   129  double res = 1;
   130
   131  if (y < 0)
   132          return 1 / __power_of(x, -y);
   133
   134  for (i = 0; i < y; i++)
   135          res *= x;
   136
   137  return res;
   138 }
