   140 static void __append_interface_block_to_file_info(const light_pcapng interface_block, light_pcapng_file_info* info)
   141 {
   142  struct _light_interface_description_block* interface_desc_block;
   143  light_option ts_resolution_option = NULL;
   144
   145  if (info->interface_block_count >= MAX_SUPPORTED_INTERFACE_BLOCKS)
   146          return;
   147
   148  light_get_block_info(interface_block, LIGHT_INFO_BODY, &interface_desc_block, NULL);
   149
   150  ts_resolution_option = light_get_option(interface_block, LIGHT_OPTION_IF_TSRESOL);
   151  if (ts_resolution_option == NULL)
   152  {
   153          info->timestamp_resolution[info->interface_block_count] = __power_of(10,-6);
   154  }
   155  else
   156  {
   157          uint8_t* raw_ts_data = (uint8_t*)light_get_option_data(ts_resolution_option);
   158          if (*raw_ts_data < 128)
   159                  info->timestamp_resolution[info->interface_block_count] = __power_of(10, (-1)*(*raw_ts_data));
   160          else
   161                  info->timestamp_resolution[info->interface_block_count] = __power_of(2, (-1)*((*raw_ts_data)-128));
   162  }
   163
   164  info->link_types[info->interface_block_count++] = interface_desc_block->link_type;
   165 }
